"use client";

import "./progress.css";
import { Progress as BaseProgress } from "@base-ui/react/progress";
import type React from "react";
import { cn } from "@/lib/cn";

import { ProgressContext, useProgressContext } from "./progress.context";
import { progressVariants, type ProgressVariants } from "./progress.variants";

export type ProgressProps = ProgressVariants & React.ComponentProps<typeof BaseProgress.Root>;

export const ProgressRoot = ({ children, className, size, ...props }: ProgressProps) => {
  const slots = progressVariants({ size });

  return (
    <ProgressContext.Provider value={{ slots }}>
      <BaseProgress.Root className={cn(slots.root(), className)} {...props}>
        {children}
      </BaseProgress.Root>
    </ProgressContext.Provider>
  );
};

export type ProgressTrackProps = React.ComponentProps<typeof BaseProgress.Track>;

export const ProgressTrack = ({ className, ...props }: ProgressTrackProps) => {
  const { slots } = useProgressContext();
  return <BaseProgress.Track className={cn(slots.track(), className)} {...props} />;
};

export type ProgressIndicatorProps = React.ComponentProps<typeof BaseProgress.Indicator>;

export const ProgressIndicator = ({ className, ...props }: ProgressIndicatorProps) => {
  const { slots } = useProgressContext();
  return <BaseProgress.Indicator className={cn(slots.indicator(), className)} {...props} />;
};

export type ProgressLabelProps = React.ComponentProps<typeof BaseProgress.Label>;

export const ProgressLabel = ({ className, ...props }: ProgressLabelProps) => {
  const { slots } = useProgressContext();
  return <BaseProgress.Label className={cn(slots.label(), className)} {...props} />;
};

export type ProgressValueProps = React.ComponentProps<typeof BaseProgress.Value>;

export const ProgressValue = ({ className, ...props }: ProgressValueProps) => {
  const { slots } = useProgressContext();
  return <BaseProgress.Value className={cn(slots.value(), className)} {...props} />;
};

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const progressVariants = tv({
  slots: {
    root: "progress",
    track: "progress__track",
    indicator: "progress__indicator",
    label: "progress__label",
    value: "progress__value",
  },
  variants: {
    size: {
      sm: {
        track: "progress__track--sm",
      },
      md: {
        track: "progress__track--md",
      },
      lg: {
        track: "progress__track--lg",
      },
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export type ProgressVariants = VariantProps<typeof progressVariants>;

"use client";

import { createContext, useContext } from "react";

import { progressVariants } from "./progress.variants";

export type ProgressContext = {
  slots: ReturnType<typeof progressVariants>;
};

export const ProgressContext = createContext<ProgressContext | null>(null);

export const useProgressContext = () => {
  const context = useContext(ProgressContext);
  return context ?? { slots: progressVariants() };
};

.progress {
  @apply text-foreground grid w-full max-w-sm grid-cols-2 gap-y-1.5;
}

.progress__label {
  @apply text-foreground text-sm font-medium;
}

.progress__value {
  @apply text-muted-foreground text-right text-sm;
}

.progress__track {
  @apply bg-secondary relative col-span-2 w-full overflow-hidden rounded-full;
}

.progress__track--sm {
  @apply h-1.5;
}

.progress__track--md {
  @apply h-2.5;
}

.progress__track--lg {
  @apply h-4;
}

.progress__indicator {
  @apply bg-primary h-full w-full flex-1 transition-all duration-300 ease-in-out;
}

import {
  ProgressIndicator,
  ProgressLabel,
  ProgressRoot,
  ProgressTrack,
  ProgressValue,
} from "./progress";

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/progress/content.md
 */
export const Progress = {
  Indicator: ProgressIndicator,
  Label: ProgressLabel,
  Root: ProgressRoot,
  Track: ProgressTrack,
  Value: ProgressValue,
};

export { ProgressIndicator, ProgressLabel, ProgressRoot, ProgressTrack, ProgressValue };

export type {
  ProgressIndicatorProps,
  ProgressLabelProps,
  ProgressProps,
  ProgressTrackProps,
  ProgressValueProps,
} from "./progress";
export { ProgressContext, useProgressContext } from "./progress.context";
export { type ProgressVariants, progressVariants } from "./progress.variants";
